function buildTrendLabels(e){return e.map(e=>new Date(e.date).toLocaleDateString("ru-RU",{day:"numeric",month:"short"}))}function buildTrendDataset({label:e,values:r,borderColor:a,backgroundColor:o}){return{label:e,data:r,borderColor:a,backgroundColor:o,fill:!0,tension:.4,pointRadius:3}}function buildTrendScale({hideGrid:e=!1}={}){return{grid:e?{display:!1}:{color:"rgba(0,0,0,0.05)"},ticks:{color:"rgba(0,0,0,0.5)",font:{size:10}},...e?{}:{beginAtZero:!0}}}export function getTrendChartConfig(e){return{type:"line",data:{labels:buildTrendLabels(e),datasets:[buildTrendDataset({label:"Заработано",values:e.map(e=>e.earned),borderColor:"#4ade80",backgroundColor:"rgba(74, 222, 128, 0.1)"}),buildTrendDataset({label:"Потрачено",values:e.map(e=>e.spent),borderColor:"#f87171",backgroundColor:"rgba(248, 113, 113, 0.1)"})]},options:{responsive:!0,maintainAspectRatio:!1,plugins:{legend:{display:!0,position:"top",align:"end",labels:{color:"rgba(0,0,0,0.7)",font:{size:11,weight:"600"},usePointStyle:!0,boxWidth:8}}},scales:{y:buildTrendScale(),x:buildTrendScale({hideGrid:!0})}}}}